#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int p=argc>1?atoi(argv[1]):5,N=p*p*p, n=argc>2?atoi(argv[2]):1000000;mt19937 rng(732921); vector<array<int,4>> perms;vector<int>sgn;array<int,4>z={0,1,2,3};do {int inv=0;for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)inv+=z[i]>z[j];perms.push_back(z);sgn.push_back(inv%2?-1:1);}while(next_permutation(z.begin(),z.end()));for(int it=0;it<n;it++){array<int,4>R,C;for(auto *v:{&R,&C}) {set<int>s;for(int i=0;i<4;i++){int x;do{x=rng()%N;}while(s.count(x%(p*p)));s.insert(x%(p*p));(*v)[i]=x;}}map<int,int> coeff;for(int k=0;k<24;k++){int e=0;for(int i=0;i<4;i++)e+=R[i]*C[perms[k][i]];coeff[e%N]+=sgn[k];}bool zero=true;for(auto [e,c]:coeff)if(c){int base=e%(p*p);for(int t=0;t<p;t++)if(coeff[base+t*p*p]!=c){zero=false;break;}if(!zero)break;}if(zero){cout<<"COUNTER ";for(int x:R)cout<<x<<",";cout<<" / ";for(int x:C)cout<<x<<",";cout<<"\n";return 1;}}cout<<"no counter p="<<p<<" n="<<n<<"\n";}
